"use strict";
import { Token } from "@uniswap/sdk-core";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import PoolAndGaugeAddress from "components/PoolAndGaugeAddress";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useEffect, useMemo, useRef, useState } from "react";
import { Delete } from "react-feather";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { selectSelectedLock, updatePendingVoteWeight } from "state/voting/slice";
import styled from "styled-components";
import { Flex, Text, styled as UiStyled, useMedia, useSporeColors } from "ui/src";
import { GoldenVerified, InfoCircleFilled } from "ui/src/components/icons";
import { useChainId } from "wagmi";
const StyledInput = styled.input`
  text-align: right;
  padding: 8px 0;
  background-color: transparent;
  border: none;
  outline: none;
  max-width: 140px;
  width: 100%;
  font-size: 18px;
  @media (max-width: 768px) {
    font-size: 14px;
    padding: 3px 0;
  }
`;
const StyledButton = styled.button`
  all: unset;
  padding: 2px 6px;
  background-color: ${(props) => props.$bgColor};
  border-radius: 999px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-size: 11px;
  &:hover {
    opacity: 0.7;
  }
`;
const SubTitle = UiStyled(Text, {
  variant: "body3",
  color: "$neutral3"
});
const ItemWrap = UiStyled(Flex, {
  flexDirection: "column",
  gap: "$spacing24",
  justifyContent: "space-between",
  backgroundColor: "$slate",
  borderRadius: "$rounded12",
  p: "$spacing12",
  alignItems: "flex-end",
  $xl: {
    flexDirection: "row"
  }
});
const CustomTextSmall = UiStyled(Text, {
  variant: "body4"
});
const CustomTextLarge = UiStyled(Text, {
  variant: "body2"
});
export default function VoteAllocationRow({ vote, poolWeight, totalWeight, gaugeApr }) {
  const dispatch = useAppDispatch();
  const selectedLock = useAppSelector(selectSelectedLock);
  const inputRef = useRef(null);
  const [inputValue, setInputValue] = useState("0");
  const colors = useSporeColors();
  const media = useMedia();
  const chainId = useChainId();
  useEffect(() => {
    if (vote.percentage > 0) {
      setInputValue(vote.percentage.toFixed(1));
    }
  }, [vote.poolAddress]);
  const calculatedAPR = useMemo(() => {
    if (!gaugeApr || gaugeApr.aprPercent === void 0 || !Number.isFinite(gaugeApr.aprPercent)) {
      return "N/A";
    }
    return `${gaugeApr.aprPercent.toFixed(2)}%`;
  }, [gaugeApr]);
  const formattedTVL = useMemo(() => {
    if (!vote.pool?.tvlUSD || vote.pool.tvlUSD === 0) {
      return "-";
    }
    const tvl = vote.pool.tvlUSD;
    if (tvl < 1e3) {
      return `$${tvl.toFixed(2)}`;
    }
    if (tvl < 1e6) {
      return `$${(tvl / 1e3).toFixed(2)}K`;
    }
    return `$${(tvl / 1e6).toFixed(2)}M`;
  }, [vote.pool?.tvlUSD]);
  const estimatedRewards = useMemo(() => {
    if (!selectedLock?.votingPower || !vote.pool?.epochStats?.rewardPerVeUsd) {
      return "-";
    }
    const rewardPerVeUsd = vote.pool.epochStats.rewardPerVeUsd;
    if (!rewardPerVeUsd || rewardPerVeUsd <= 0) {
      return "-";
    }
    const userTotalVotingPower = parseFloat(selectedLock.votingPower) / 1e18;
    if (!Number.isFinite(userTotalVotingPower) || userTotalVotingPower <= 0) {
      return "-";
    }
    const userVotingPowerForPool = vote.percentage / 100 * userTotalVotingPower;
    if (userVotingPowerForPool <= 0) {
      return "-";
    }
    const estimatedRewardsUsd = userVotingPowerForPool * rewardPerVeUsd;
    if (!Number.isFinite(estimatedRewardsUsd) || estimatedRewardsUsd <= 0) {
      return "-";
    }
    if (estimatedRewardsUsd < 0.01) {
      return "~$<0.01";
    } else if (estimatedRewardsUsd < 1e3) {
      return `~$${estimatedRewardsUsd.toFixed(2)}`;
    } else if (estimatedRewardsUsd < 1e6) {
      return `~$${(estimatedRewardsUsd / 1e3).toFixed(2)}K`;
    } else {
      return `~$${(estimatedRewardsUsd / 1e6).toFixed(2)}M`;
    }
  }, [selectedLock?.votingPower, vote.pool?.epochStats?.rewardPerVeUsd, vote.percentage]);
  const handleChange = (text) => {
    const numericValue = text.replace(/[^0-9.]/g, "");
    const num = parseFloat(numericValue) || 0;
    const clampedNum = Math.min(100, Math.max(0, num));
    setInputValue(numericValue);
    dispatch(
      updatePendingVoteWeight({
        poolAddress: vote.poolAddress,
        weight: clampedNum
      })
    );
  };
  const handlePercentageClick = (percentage) => {
    setInputValue(percentage.toString());
    dispatch(
      updatePendingVoteWeight({
        poolAddress: vote.poolAddress,
        weight: percentage
      })
    );
  };
  const CustomText = media.md ? CustomTextSmall : CustomTextLarge;
  const inputStyle = useMemo(() => ({ color: colors.neutral1.val }), [colors.neutral1.val]);
  const buttonsArray = [10, 25, 50, 75, 100];
  const currencies = useMemo(() => {
    if (!vote.pool?.token0 || !vote.pool?.token1) return [void 0, void 0];
    try {
      const token0 = new Token(
        chainId,
        vote.pool.token0.id,
        parseInt(vote.pool.token0.decimals ?? "18"),
        vote.pool.token0.symbol,
        vote.pool.token0.name
      );
      const token1 = new Token(
        chainId,
        vote.pool.token1.id,
        parseInt(vote.pool.token1.decimals ?? "18"),
        vote.pool.token1.symbol,
        vote.pool.token1.name
      );
      return [token0, token1];
    } catch (error) {
      console.warn("Failed to create tokens for pool logos:", error);
      return [void 0, void 0];
    }
  }, [vote.pool?.token0, vote.pool?.token1, chainId]);
  const poolName = vote.pool?.token0?.symbol && vote.pool?.token1?.symbol ? `${vote.pool.token0.symbol}/${vote.pool.token1.symbol}` : `${vote.poolAddress.slice(0, 6)}...${vote.poolAddress.slice(-4)}`;
  const currentVotePercentage = useMemo(() => {
    if (!poolWeight || totalWeight === 0) return 0;
    return poolWeight / totalWeight * 100;
  }, [poolWeight, totalWeight]);
  const currentVeABXAmount = useMemo(() => {
    if (!poolWeight || totalWeight === 0) return "0";
    const veABXAmount = poolWeight;
    if (veABXAmount >= 1e6) {
      return `${(veABXAmount / 1e6).toFixed(2)}M`;
    } else if (veABXAmount >= 1e3) {
      return `${(veABXAmount / 1e3).toFixed(2)}K`;
    } else {
      return veABXAmount.toFixed(2);
    }
  }, [poolWeight, totalWeight]);
  return <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "12fr 8fr 8fr 8fr 10fr" }}
    gap={"$spacing12"}
    $xl={{ gridTemplateColumns: "1fr", gap: "$spacing8" }}
    backgroundColor={"$surface1Hovered"}
    p={"$padding12"}
    transition="background-color 0.2s ease"
    hoverStyle={{ backgroundColor: "$surface2" }}
    borderRadius={"$rounded12"}
  >
      {
    /* Pool Info */
  }
      <Flex $xl={{ mb: "$gap20" }} group className="info" row gap={"$gap12"} alignItems="center">
        <DoubleCurrencyLogo currencies={currencies} size={40} />

        <Flex flexDirection="column" justifyContent="center" gap={"$gap4"}>
          <Flex row gap={"$gap8"} alignItems="center">
            <Text variant="subheading1">{poolName}</Text>
            <GoldenVerified size={"$icon.18"} />
            {vote.pool && <MouseoverTooltip
    text="Pool Trading Fee"
    size={TooltipSize.Max}
    placement="top"
  >
                <Text
    backgroundColor={"$surface3"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant="body3"
    cursor="pointer"
    hoverStyle={{ backgroundColor: "$surface3Hovered" }}
  >
                  {(() => {
    if (vote.pool?.fee) {
      const feeNum = parseFloat(vote.pool.fee);
      if (Number.isFinite(feeNum) && feeNum > 0) {
        const percent = feeNum / 1e4;
        const formatted = percent >= 1 ? percent.toString() : percent.toFixed(2).replace(/\.?0+$/, "") || "0";
        return `${formatted}%`;
      }
    }
    if (vote.pool?.poolType === "V2") {
      return vote.pool.stable ? "0.05%" : "0.3%";
    }
    return "0.3%";
  })()}
                </Text>
              </MouseoverTooltip>}
            <MouseoverTooltip
    text={<PoolAndGaugeAddress poolAddress={vote.pool?.poolId} gaugeAddress={vote.pool?.id} />}
    size={TooltipSize.Max}
    placement="top"
  >
              <Flex
    cursor="pointer"
    transition="opacity 0.3s ease"
    opacity={0}
    $md={{ opacity: 1 }}
    $group-hover={{ opacity: 1 }}
  >
                <InfoCircleFilled size={"$icon.18"} color={"$neutral2"} />
              </Flex>
            </MouseoverTooltip>
          </Flex>
          <Text variant="body3" fontWeight={"$medium"} color={"$neutral2"}>
            TVL: {formattedTVL}
          </Text>
        </Flex>
      </Flex>
      <ItemWrap>
        {
    /* APR Info */
  }
        <Flex
    flexDirection="column"
    $xl={{ flexDirection: "row", gap: "$gap12", justifyContent: "space-between" }}
    gap={"$gap12"}
  >
          <SubTitle>APR</SubTitle>
          <CustomText>{calculatedAPR}</CustomText>
        </Flex>
      </ItemWrap>
      <ItemWrap>
        {
    /* Current Votes */
  }
        <Flex
    flexDirection="column"
    alignItems="flex-end"
    $xl={{ flexDirection: "row", gap: "$gap12", justifyContent: "space-between", alignItems: "center" }}
    gap={"$spacing12"}
  >
          <SubTitle>Current Votes</SubTitle>
          <Flex flexDirection="column" alignItems="flex-end" gap={"$gap4"}>
            <CustomText>{currentVotePercentage.toFixed(2)}%</CustomText>
            <Text variant="body4" color="$neutral2">{currentVeABXAmount} veABX</Text>
          </Flex>
        </Flex>
      </ItemWrap>
      <ItemWrap>
        {
    /* Est. Rewards */
  }
        <Flex
    flexDirection="column"
    alignItems="flex-end"
    $xl={{ flexDirection: "row", gap: "$gap12", justifyContent: "space-between", alignItems: "center" }}
    gap={"$spacing12"}
  >
          <SubTitle>Est. Rewards</SubTitle>
          <CustomText>{estimatedRewards}</CustomText>
        </Flex>
      </ItemWrap>
      <ItemWrap $xl={{ justifyContent: "flex-end" }}>
        {
    /* Voting Power Percentage */
  }
        <Flex flexDirection="column" gap={"$spacing12"} alignItems="flex-end" width={"100%"}>
          <SubTitle>Voting Power %</SubTitle>
          <Flex
    row
    px="$spacing8"
    py={"$spacing4"}
    borderWidth={1}
    borderColor={"$surface3"}
    justifyContent="space-between"
    alignItems="center"
    gap={"$gap4"}
    borderRadius={"$rounded12"}
    overflow="hidden"
    flex={1}
    onPress={() => inputRef.current?.focus()}
    $platform-web={{
      focusWithinStyle: { borderColor: "$neutral2" }
    }}
    transition="border-color 0.3s ease"
  >
            <Text>%</Text>
            <StyledInput
    ref={inputRef}
    onChange={(e) => handleChange(e.target.value)}
    type="text"
    value={inputValue}
    style={inputStyle}
    placeholder="0"
  />
          </Flex>

          <Flex row gap={"$gap4"} alignItems="center" justifyContent="flex-end">
            <StyledButton $bgColor={colors.surface2Hovered.val} onClick={() => handlePercentageClick(0)}>
              <Delete size={12} color={colors.neutral1.val} />
            </StyledButton>
            {buttonsArray.map((button, btnIndex) => <StyledButton key={btnIndex} $bgColor={colors.surface2Hovered.val} onClick={() => handlePercentageClick(button)}>
                <Text variant="body4" textWrap="nowrap">
                  {button}%
                </Text>
              </StyledButton>)}
          </Flex>
        </Flex>
      </ItemWrap>
    </Flex>;
}
